(()=>{function sync(){const bands=[...document.querySelectorAll('.sample-band')],source=bands[0];bands.slice(1).forEach(b=>{b.querySelector('strong').textContent=source.querySelector('strong').textContent;b.querySelector('small').textContent=source.querySelector('small').textContent;});for(const persona of ['quality','procurement'])for(const key of ['waste','cost','carbon']){const source=document.getElementById(key+'-bars'),target=document.getElementById(persona+'-'+key+'-bars');if(!source||!target)continue;target.innerHTML=source.innerHTML;target.setAttribute('aria-label',source.getAttribute('aria-label'));}}document.addEventListener('resolve-model',sync);sync();})();